(function () {
  var m = {"COP315-R": {"abstract": "Tracking patch compliance across hundreds of accounts is manual, slow, and hard to prove to auditors. In this hands-on builders' session, you automate patching and continuous compliance in your environment, then let AI do the heavy lifting: generate a multi-account compliance dashboard with Apps in Amazon Quick and answer compliance questions with natural language instead of hand-building reports. By the end, you'll know how to turn raw patch data into audit-ready answers on demand.", "language": "en"},"COP315-R1": {"abstract": "Tracking patch compliance across hundreds of accounts is manual, slow, and hard to prove to auditors. In this hands-on builders' session, you automate patching and continuous compliance in your environment, then let AI do the heavy lifting: generate a multi-account compliance dashboard with Apps in Amazon Quick and answer compliance questions with natural language instead of hand-building reports. By the end, you'll know how to turn raw patch data into audit-ready answers on demand.", "language": "en"},"COP316-R": {"abstract": "Most teams discover resilience gaps during outages, not before. In this interactive chalk talk, you'll use the next generation of AWS Resilience Hub to map user journeys, define recovery objectives, discover dependencies, and run AI-powered failure mode assessments. You'll implement high availability improvements, deploy multi-region disaster recovery, and run the right automated disaster recovery tests that fit your architecture and use case. Walk away with a repeatable framework you can plug into your own environment next week.", "language": "en"},"COP316-R1": {"abstract": "Most teams discover resilience gaps during outages, not before. In this interactive chalk talk, you'll use the next generation of AWS Resilience Hub to map user journeys, define recovery objectives, discover dependencies, and run AI-powered failure mode assessments. You'll implement high availability improvements, deploy multi-region disaster recovery, and run the right automated disaster recovery tests that fit your architecture and use case. Walk away with a repeatable framework you can plug into your own environment next week.", "language": "en"},"COP317-R": {"abstract": "AWS DevOps Agent is your always-available operations teammate that investigates, resolves, and proactively prevents incidents. In this hands-on workshop, take the on-call seat: inject real faults into a live microservices store on Amazon EKS, partner with the agent to root-cause them in minutes, and judge its mitigation plans. Then extend it — encode your team's expertise as skills, connect custom MCP tools, automate investigations from alarms, and approve agent-executed fixes. Leave with production-ready patterns that keep your infrastructure running.", "language": "en"},"COP317-R1": {"abstract": "AWS DevOps Agent is your always-available operations teammate that investigates, resolves, and proactively prevents incidents. In this hands-on workshop, take the on-call seat: inject real faults into a live microservices store on Amazon EKS, partner with the agent to root-cause them in minutes, and judge its mitigation plans. Then extend it — encode your team's expertise as skills, connect custom MCP tools, automate investigations from alarms, and approve agent-executed fixes. Leave with production-ready patterns that keep your infrastructure running.", "language": "en"},"COP318-R": {"abstract": "You need visibility into your AI workloads before they reaches production, not after they fails, yet most teams have no telemetry on their agents at all. In this workshop, you instrument a live AI agent end to end, capturing token cost, latency, tool calls, and reasoning traces. You make the instrumentation decisions, build the dashboards and anomaly alerts. Leave with a working setup you can apply to your own agentic workloads.", "language": "en"},"COP318-R1": {"abstract": "You need visibility into your AI workloads before they reaches production, not after they fails, yet most teams have no telemetry on their agents at all. In this workshop, you instrument a live AI agent end to end, capturing token cost, latency, tool calls, and reasoning traces. You make the instrumentation decisions, build the dashboards and anomaly alerts. Leave with a working setup you can apply to your own agentic workloads.", "language": "en"},"COP319-R": {"abstract": "Your developers are burning tokens on AI coding agents with zero visibility. Claude Code and OpenAI Codex run on laptops, outside your perimeter, with no telemetry reaching your observability backend. In this session, we fix that. Using native OpenTelemetry export and Amazon CloudWatch's OTLP endpoint with a single bearer token, with no collectors, no sidecars, no credential wiring, we ship metrics (token usage, cost, productivity), logs (tool decisions, errors), and traces (agent reasoning chains) directly from developer machines. Then we build a live dashboard with per-team cost attribution and anomaly alerting, all queryable with PromQL. Walk out ready to deploy in minutes.", "language": "en"},"COP319-R1": {"abstract": "Your developers are burning tokens on AI coding agents with zero visibility. Claude Code and OpenAI Codex run on laptops, outside your perimeter, with no telemetry reaching your observability backend. In this session, we fix that. Using native OpenTelemetry export and Amazon CloudWatch's OTLP endpoint with a single bearer token, with no collectors, no sidecars, no credential wiring, we ship metrics (token usage, cost, productivity), logs (tool decisions, errors), and traces (agent reasoning chains) directly from developer machines. Then we build a live dashboard with per-team cost attribution and anomaly alerting, all queryable with PromQL. Walk out ready to deploy in minutes.", "language": "en"},"COP320-R": {"abstract": "In this builder session, learn how to create custom SRE agents that turn a simple prompt into automated, environment-specific operational workflows. Using pre-configured tools and integrations, you'll define agents tailored to your priorities, whether that's anomaly detection, performance optimization, cost analysis, or resiliency recommendations. See how agents combine real-time observability data with structured reasoning to surface actionable improvements without manual investigation. Walk away with hands-on experience designing an agent that monitors your operational patterns and proactively recommends next steps, so your team spends less time diagnosing and more time shipping.", "language": "en"},"COP320-R1": {"abstract": "In this builder session, learn how to create custom SRE agents that turn a simple prompt into automated, environment-specific operational workflows. Using pre-configured tools and integrations, you'll define agents tailored to your priorities, whether that's anomaly detection, performance optimization, cost analysis, or resiliency recommendations. See how agents combine real-time observability data with structured reasoning to surface actionable improvements without manual investigation. Walk away with hands-on experience designing an agent that monitors your operational patterns and proactively recommends next steps, so your team spends less time diagnosing and more time shipping.", "language": "en"},"COP321": {"abstract": "Your AZ recovery plan and your Region failover plan were probably built by different teams, tested at different times, and have never run together. The result: untested failover paths that turn outages into incidents. Explore how to build a unified recovery framework with Amazon Application Recovery Controller. From zonal autoshift for rapid single-AZ mitigation, to Region switch for cross-Region failover, learn how ARC unifies both layers into a single orchestrated approach. Then discover how to run automated resilience tests that continuously validate your recovery posture before a real event forces the question.", "language": "en"},"COP322-R": {"abstract": "When an application slows down, the cause can hide anywhere from the frontend to the database, and siloed tools make teams guess. In this workshop, you will build full-stack observability across application, infrastructure, and database layers, bringing RDS and Aurora signals and database logs into one store and correlating them with audit activity. You decide what to trace and build the dashboards that connect a symptom to its root cause. Leave with skills to trace any slowdown across layers in a single pane.", "language": "en"},"COP322-R1": {"abstract": "When an application slows down, the cause can hide anywhere from the frontend to the database, and siloed tools make teams guess. In this workshop, you will build full-stack observability across application, infrastructure, and database layers, bringing RDS and Aurora signals and database logs into one store and correlating them with audit activity. You decide what to trace and build the dashboards that connect a symptom to its root cause. Leave with skills to trace any slowdown across layers in a single pane.", "language": "en"},"COP323-R": {"abstract": "AI agents act fast. Auditors ask questions slowly. Bridge that gap with an observability layer that satisfies both. This session walks through Amazon Bedrock AgentCore traces across multi-agent workflows, Amazon CloudWatch for decision-level visibility and drift detection, escalation thresholds that keep humans in the loop, and patterns for reconstructing agent reasoning after the fact. Walk away with a practical audit loop you can implement for agents running in production.", "language": "en"},"COP323-R1": {"abstract": "AI agents act fast. Auditors ask questions slowly. Bridge that gap with an observability layer that satisfies both. This session walks through Amazon Bedrock AgentCore traces across multi-agent workflows, Amazon CloudWatch for decision-level visibility and drift detection, escalation thresholds that keep humans in the loop, and patterns for reconstructing agent reasoning after the fact. Walk away with a practical audit loop you can implement for agents running in production.", "language": "en"},"COP324-R": {"abstract": "Embed FinOps as an operational discipline using AI-powered cost optimization. This hands-on workshop demonstrates how to shift left on cloud financial management by integrating cost discipline throughout development. Explore AWS services for automated optimizations, rightsizing, and savings plans. Gain experience with AI/ML and container workload cost allocation, multi-cloud reporting, and AI-powered spend analysis. Implement automated strategies using real workload data. Laptop required", "language": "en"},"COP324-R1": {"abstract": "Embed FinOps as an operational discipline using AI-powered cost optimization. This hands-on workshop demonstrates how to shift left on cloud financial management by integrating cost discipline throughout development. Explore AWS services for automated optimizations, rightsizing, and savings plans. Gain experience with AI/ML and container workload cost allocation, multi-cloud reporting, and AI-powered spend analysis. Implement automated strategies using real workload data. Laptop required", "language": "en"},"COP325-R": {"abstract": "AI agents are non-deterministic, multi-step, and make autonomous decisions and traditional APM isn't enough. Explore observability patterns for agentic workloads: reasoning chain tracing, token cost attribution, guardrail monitoring, and multi-agent coordination. We'll whiteboard architectures in real time. Bring your toughest production agent monitoring questions and leave with actionable patterns.", "language": "en"},"COP325-R1": {"abstract": "AI agents are non-deterministic, multi-step, and make autonomous decisions and traditional APM isn't enough. Explore observability patterns for agentic workloads: reasoning chain tracing, token cost attribution, guardrail monitoring, and multi-agent coordination. We'll whiteboard architectures in real time. Bring your toughest production agent monitoring questions and leave with actionable patterns.", "language": "en"},"COP326": {"abstract": "The challenge most companies face is knowing where they stand with resilience, being willing to validate their assumptions safely, and disciplined enough to continuously improve without slowing delivery. In this session, we walk through Autodesk's journey with resilience testing and automated recovery failover as proof that investing in validation pays off, and you leave with a repeatable lifecycle for turning your own assumptions into proven capabilities. Discover how the next-generation AWS Resilience Hub handles the tedious work like mapping dependencies, assessing posture, and preconfiguring resilience tests, leaving your teams to focus on closing the gap between the system you think you operate and the one you actually do.", "language": "en"},"COP328-R": {"abstract": "AI spend starts with model tokens but often misses costs from agent runtimes, memory, data, and supporting services. In this chalk talk, we'll map an AI workload from architecture to bill, then apply a practical framework to measure, attribute, optimize, and govern its cost and value. Using AWS FinOps Agent as an example, we'll examine how its architecture creates costs across Amazon Bedrock and supporting services, and how to govern those costs. Bring your AI cost challenge and leave with a model that helps FinOps and engineering teams assign ownership, find waste, and set effective controls.", "language": "en"},"COP328-R1": {"abstract": "AI spend starts with model tokens but often misses costs from agent runtimes, memory, data, and supporting services. In this chalk talk, we'll map an AI workload from architecture to bill, then apply a practical framework to measure, attribute, optimize, and govern its cost and value. Using AWS FinOps Agent as an example, we'll examine how its architecture creates costs across Amazon Bedrock and supporting services, and how to govern those costs. Bring your AI cost challenge and leave with a model that helps FinOps and engineering teams assign ownership, find waste, and set effective controls.", "language": "en"},"COP329-R": {"abstract": "Managing Savings Plans well is a continuous job. In this chalk talk, we discuss approaches to making commitment purchases more intelligent and less manual. We will cover how you can build a purchasing cadence that incorporates your organization's demand patterns through automation and the right level of human oversight. We'll also cover Automation, a feature within AWS Compute Optimizer that enables you to apply optimization recommendations to your AWS resources, which can help you reduce costs and improve performance. Bring your questions and challenges.", "language": "en"},"COP329-R1": {"abstract": "Managing Savings Plans well is a continuous job. In this chalk talk, we discuss approaches to making commitment purchases more intelligent and less manual. We will cover how you can build a purchasing cadence that incorporates your organization's demand patterns through automation and the right level of human oversight. We'll also cover Automation, a feature within AWS Compute Optimizer that enables you to apply optimization recommendations to your AWS resources, which can help you reduce costs and improve performance. Bring your questions and challenges.", "language": "en"},"COP330": {"abstract": "As your compute spreads across multiple clouds and on-premises, every environment ends up with its own agents, tooling, and consoles. Patching, access, and monitoring happen a different way in each one, and no single view shows what is running or how it behaves. In this chalk talk, we whiteboard how to bring every instance under one operational model with AWS Systems Manager, no matter where it runs, and then get metrics and logs from all of them into Amazon CloudWatch. We work through the tradeoffs and patterns that hold at scale. Leave able to run and observe your whole fleet as one.", "language": "en"},"COP331-R": {"abstract": "Most teams turn on AI-driven operations before deciding what they actually want it to handle, investment is racing ahead of maturity. This chalk talk works through an AIOps strategy at the whiteboard, using real support-case patterns showing that most critical failures are catchable before they reach production. We map the two halves that teams miss: using AI to run operations and the operational foundations that let AI scale safely, such as cost, security, and organizational readiness. We discuss what to automate, what stays human, and where agents earn autonomy. Leave with a foundational framework and a maturity checklist for your team.", "language": "en"},"COP331-R1": {"abstract": "Most teams turn on AI-driven operations before deciding what they actually want it to handle, investment is racing ahead of maturity. This chalk talk works through an AIOps strategy at the whiteboard, using real support-case patterns showing that most critical failures are catchable before they reach production. We map the two halves that teams miss: using AI to run operations and the operational foundations that let AI scale safely, such as cost, security, and organizational readiness. We discuss what to automate, what stays human, and where agents earn autonomy. Leave with a foundational framework and a maturity checklist for your team.", "language": "en"},"COP332": {"abstract": "Static code analysis tells you what to modernize. It doesn't tell you what breaks when you do. Runtime dependencies, real traffic patterns, and operational risk stay invisible until cutover, when surprises are most expensive. AWS DevOps Agent adds the missing ingredient: production intelligence fed directly into your AWS Transform modernization plan. The result is assessments grounded in reality and migrations that stay safe through execution. In this chalk talk, we discuss how to incorporate production intelligence from DevOps Agent into an automated migration pipeline by Transform Custom. Bring your modernization challenges to discuss.", "language": "en"},"COP333": {"abstract": "Inconsistent tags make it hard to see what runs where. In this code talk, we build automation that keeps tagging clean at scale: a tagging schema that defines the keys and values that matter, an AWS Config rule that flags non-compliant resources, and an AWS Systems Manager Automation runbook that remediates them automatically or with approval. We also query untagged resources across thousands of resources and multi accounts. Leave with working code you can adapt for cost allocation, access scoping, and AI-assisted root-cause analysis.", "language": "en"},"COP334": {"abstract": "Meeting your recovery time and point objectives is non-negotiable. For your critical workloads, that means orchestrated, tier-aware recovery within minutes, with a plan you've actually tested. Most teams haven't, because testing often means disrupting production. So, the plan stays on the shelf and RTOs stay theoretical. In this session, see AWS Elastic Disaster Recovery replicate servers into low-cost staging and recover the full stack in the right order, in minutes, then rehearse the same failover without production noticing. Learn how to run non-disruptive recovery drills against your own environment and prove your RTOs before an incident does it for you.", "language": "en"},"COP335": {"abstract": "Give your operations teams the full picture without jumping between tools. Learn how to bring logs, metrics, and traces into a unified data store for analytics and improved troubleshooting. Instead of just storing logs and treating logs as text to grep during an outage, use centralization rules that bring telemetry together across accounts and regions, telemetry pipelines that enrich and route data in flight, intelligence tiering that matches storage cost to query value, and AI-assisted log analytics that surface answers instead of waiting for you to ask the right question. This is about making logs work for you — not the other way around. You'll leave with a clear architecture for unified log analytics you can take back to your org and put into production.", "language": "en"},"COP336": {"abstract": "Getting full visibility across your stack shouldn't mean stitching together disconnected tools and proprietary formats. When you standardize on OpenTelemetry with AWS, you get rich, unified telemetry from metrics, logs, and traces across your containers, Kubernetes clusters, AI workloads, and everything in between. Collect deep telemetry using OTLP ingestion, PromQL querying, and automatic enrichment with Amazon CloudWatch's native OpenTelemetry. No fragmented data. No vendor lock-in. Just one telemetry foundation that gives you the context you need to understand what's happening across your entire environment. Learn how to achieve richer data, unified observability, and a production-ready architecture that scales with you.", "language": "en"},"COP337": {"abstract": "Agentic applications need different access patterns and tooling than traditional apps. Teams often stitch together several tools and act as the human orchestrator just to answer a basic question: is my agent doing what the business needs? That gets harder when the agent runs on one cloud and calls models or APIs on another. In this session, we show how CloudWatch Omni brings AI agents and applications across clouds into one view, accelerating root cause whether its due to performance, availability or response quality.", "language": "en"},"COP338": {"abstract": "Your app is slow, but is it the code, the container, or the underlying host? When your stack spans clouds, hybrid, and on-prem, correlating application performance to infrastructure health means jumping between tools and guessing at root cause. Join this session as we walk through how to map application signals such as traces, errors, and latency directly to the infrastructure, regardless of where it runs. You'll see how to pinpoint whether the problem is your app or the compute it sits on, without stitching dashboards together manually.", "language": "en"},"COP339": {"abstract": "You've got logs flowing from everywhere, but when an issue spans multiple accounts or regions, you're stuck jumping between consoles trying to piece together what happened. In this chalk talk, we'll whiteboard the end-to-end path a log takes from ingestion pipeline to a unified data layer to log analytics. We'll break down where visibility gaps form and why. Learn how you can connect these layers to trace a problem across your entire environment without losing context.", "language": "en"},"COP340-R": {"abstract": "Most observability strategies were built for a pre-AI world and are no longer enough. Your data foundation remains critical, but the way you use that data is changing fast. In this chalk talk, we explore what stays the same, what must evolve, and what's new as AI reshapes observability. We'll cover the shift from static dashboards to dynamic experiences, from reactive alarms to AI-driven insights, and the new questions you need to answer, like how well your agents are performing. Join us as we share what AWS is learning as we embrace AI-led observability.", "language": "en"},"COP340-R1": {"abstract": "Most observability strategies were built for a pre-AI world and are no longer enough. Your data foundation remains critical, but the way you use that data is changing fast. In this chalk talk, we explore what stays the same, what must evolve, and what's new as AI reshapes observability. We'll cover the shift from static dashboards to dynamic experiences, from reactive alarms to AI-driven insights, and the new questions you need to answer, like how well your agents are performing. Join us as we share what AWS is learning as we embrace AI-led observability.", "language": "en"},"COP341": {"abstract": "In this talk, we'll describe some of the resilience testing we've been doing in AWS. We'll talk a bit about the Game Day Region, why it exists, and how we use it. We'll talk about the types of test we run, the philosophy behind them, and some takeaways that you, our customers, can also apply.", "language": "en"},"COP342-R": {"abstract": "At scale, container environments generate metrics and logs that increase both cost and noise for engineering teams. This session explores architectural strategies for managing observability data across containerized workloads using OpenTelemetry. Learn how to control metric cardinality, design sampling policies that preserve critical signals, and evaluate managed backend tradeoffs. You'll leave with a framework for building cost-aware container observability.", "language": "en"},"COP342-R1": {"abstract": "At scale, container environments generate metrics and logs that increase both cost and noise for engineering teams. This session explores architectural strategies for managing observability data across containerized workloads using OpenTelemetry. Learn how to control metric cardinality, design sampling policies that preserve critical signals, and evaluate managed backend tradeoffs. You'll leave with a framework for building cost-aware container observability.", "language": "en"},"COP343": {"abstract": "In this live demo, we take an uninstrumented service from zero observability to correlated metrics, logs, and traces in minutes using Open Telemetry and Amazon CloudWatch. Walk through the shortest path to production-grade instrumentation: SDK configuration, collector setup, signal routing, and surfacing the first actionable insight.", "language": "en"},"COP344-S": {"abstract": "Enterprises now ship software that reasons and acts on its own. The infrastructure underneath still waits for a human to edit YAML. This session makes the case that autonomous workloads demand autonomous infrastructure, and shows what it looks like on Amazon EKS today: agents held to fractional GPU allocations that track real consumption, pod requests that stay honest as behavior drifts, and Karpenter consolidating nodes fed by accurate signals. You'll hear how enterprises run this in production with ScaleOps, and where autonomous resource management goes next. Leave with a blueprint for infrastructure that manages itself. This presentation is brought to you by ScaleOps, an AWS Partner.", "language": "en"},"COP345-S": {"abstract": "The biggest barrier to autonomous operations isn't capability, it's trust.Handing an incident to an autonomous agent raises a fair question. How do you know it is not guessing from raw log lines. This session shows how NeuBird AI reasons over your live environment and shows the causal chain behind every root cause, not a coincidence in the metrics. We’ll examine the guardrails that make production deployment safe: VPC-native execution, zero external data retention, complete auditable reasoning paths, and human-gated action approvals. Learn how to safely transition from human-driven triage to trusted, autonomous production operations on your own terms. This presentation is brought to you by NeuBird AI, an AWS Partner.", "language": "en"},"COP347-S": {"abstract": "AI gave teams a faster car. It did not fix the roads. As teams create more applications, infrastructure and complexity, the challenge shifts from moving faster to operating smarter. Enterprises need context to understand what is happening, agency to act across the tools they already use, and control to keep speed from becoming chaos. In this session, see how Terraform and Vault together with Kubernetes, Amazon Bedrock, AgentCore and IBM Concert to standardize delivery, secure access and connect application context to action across hybrid environments. This presentation is brought to you by HashiCorp, an AWS Partner.", "language": "en"},"COP348": {"abstract": "As AI adoption accelerates, organizations need visibility into who is consuming Amazon Bedrock resources and how that spend maps to business outcomes. In this lightning talk, see how to tag API calls for granular cost attribution, set real-time budgets to control AI spend, and track costs as they happen in the Billing and Cost Management console. Walk away with a practical framework for aligning AI spend to business outcomes.", "language": "en"},"COP349": {"abstract": "Multi-tenant ISVs need per-tenant observability that traditional dashboards can't deliver — aggregated metrics hide the tenant causing the problem, and shared traces don't tell you whose agent misbehaved. In this session, build a per-tenant observability stack for agents. You'll instrument agent invocations with tenant-aware traces and session replay, build tenant-scoped dashboards that surface noisy neighbors and latency outliers, and configure alerting that fires on per-tenant thresholds rather than aggregate signals. By the end, you'll have an observability setup that scales with your tenant count without a separate data pipeline — and patterns to extend it as your agent architecture grows.", "language": "en"},"COP350-S": {"abstract": "Every infrastructure change is one run: code, an engine, a plan, an apply. That run is still a wall of unstructured log text, and the questions about your estate go unanswered. Five to ask of your IaC: Did Terraform, OpenTofu, CloudFormation, Kubernetes, or Ansible run it, and does it matter? Where does the time go, and can OpenTelemetry tracing show you? What happens outside the engine: providers, state, policy-as-code, drift, queue time? What about unmanaged resources, the half of your AWS account no run ever touched? Who gets self-service, and can an AI agent be trusted with an apply? This presentation is brought to you by Spacelift, Inc., an AWS Partner.", "language": "en"},"COP351": {"abstract": "Infor (a Koch Industries company) runs one of the largest enterprise footprints on AWS. As that footprint grew, manual release gates, incident investigations, and periodic security assessments couldn't keep pace. Hear how Infor is adopting AWS agentic AI to reshape operations: DevOps Agent for incident triage and release readiness, Continuum for continuous security validation, and the Well-Architected Agentic AI Lens for production guardrails. Leave with a blueprint for agentic AI at scale.", "language": "en"},"COP352": {"abstract": "In this session, learn how a large financial institution deploys AWS DevOps Agent as an autonomous SRE teammate to reduce incident investigation time from hours to minutes and free engineering teams from reactive firefighting. Explore the architecture spanning CloudWatch, Splunk, GitHub, and Slack integrations, and see how the agent correlates telemetry across data sources to identify root causes and generate mitigation plans. Walk away with practical patterns for deploying agentic operations in regulated, compliance-sensitive environments.", "language": "en"},"COP353": {"abstract": "There's a big difference between an agent that gives you a remediation plan and one that can carry it out. In this session, see how AWS DevOps Agent goes beyond investigation to take action on operational issues across AWS, multicloud, and on-prem environments. Learn how directed actions and defense-in-depth controls govern what the agent can do, with layered opt-in, per-action approval, and built-in guardrails that keep operations safe", "language": "en"},"COP354": {"abstract": "Follow an investigation of a complex workload using AWS DevOps Agent. Trace an application-level symptom through multiple layers of your environment across AWS, multicloud, and on-prem environments. See how DevOps Agent analyzes telemetry, correlates signals across layers, identifies likely root causes, and delivers targeted remediation. Learn practical techniques for investigating workloads and reducing the manual effort of diagnosing problems across distributed environments.", "language": "en"},"COP354-R": {"abstract": "Follow an investigation of a complex workload using AWS DevOps Agent. Trace an application-level symptom through multiple layers of your environment across AWS, multicloud, and on-prem environments. See how DevOps Agent analyzes telemetry, correlates signals across layers, identifies likely root causes, and delivers targeted remediation. Learn practical techniques for investigating workloads and reducing the manual effort of diagnosing problems across distributed environments.", "language": "en"},"COP355": {"abstract": "Follow an issue from detection to resolution. In this builder's session, see how AWS DevOps Agent investigates incidents across AWS, multicloud, and on-premises environments, analyzing telemetry and correlating signals to pinpoint root causes and deliver targeted remediation. Then use the AWS DevOps Agent release management agent to review the code changes for production readiness before they reach your customers. Every review is informed by production intelligence that AWS DevOps Agent continuously builds from your environment.", "language": "en"},"COP355-R": {"abstract": "Follow an issue from detection to resolution. In this builder's session, see how AWS DevOps Agent investigates incidents across AWS, multicloud, and on-premises environments, analyzing telemetry and correlating signals to pinpoint root causes and deliver targeted remediation. Then use the AWS DevOps Agent release management agent to review the code changes for production readiness before they reach your customers. Every review is informed by production intelligence that AWS DevOps Agent continuously builds from your environment.", "language": "en"},"COP356": {"abstract": "Amazon CloudWatch Omni converges application and AI agent observability into one AI-powered experience built on open standards. In this session, instrument an agent with a popular framework and trace every LLM call, tool invocation, and reasoning step in the Trace Explorer. Run built-in evaluators to score responses for correctness, coherence, and faithfulness, then test prompt variations in the Playground and compare configurations against golden datasets with Experiments. Explore auto-discovered topology, correlate agent behavior with downstream services, and investigate issues with AWS DevOps Agent using natural language. Leave with a working observability pipeline from IDE to production and the skills to evaluate, debug, and operate agents from one pane.", "language": "en"},"COP357": {"abstract": "Get hands-on with Amazon CloudWatch Omni, the next evolution of CloudWatch that converges application and agent observability into one AI-powered solution. Instrument an agent, trace its execution, run evaluations, and experiment with prompts and models in your IDE. Explore auto-discovered topology, golden metrics, and AI-powered investigation with AWS DevOps Agent.", "language": "en"},"COP357-R": {"abstract": "Get hands-on with Amazon CloudWatch Omni, the next evolution of CloudWatch that monitors your AI stack end to end, from the agent all the way down to the self-hosted inference workload serving it, converging application and agent observability into one AI-powered solution. Instrument an agent, trace its execution, and run evaluations against golden datasets. When something degrades, explore auto-discovered topology and golden metrics to pinpoint where latency or errors creep in. Navigate from alarm to the responsible inference workload, and let Omni's AI-powered investigation trace the root cause.", "language": "en"},"COP358": {"abstract": "Traditional monitoring tools weren't built for the complexity of modern agentic and distributed applications. Teams juggle siloed dashboards, fragmented logs, and disconnected signals with no unified way to troubleshoot across agents, applications, and infrastructure. Amazon CloudWatch Omni is an AI-powered observability experience organized around your teams and the applications they run, combining OpenTelemetry interoperability with CloudWatch scale. See how you can troubleshoot applications faster and manage agents with confidence using automatic service discovery, dependency mapping, built-in evaluations, and natural-language investigation — all from the Omni UI, your IDE, or your favorite tools.", "language": "en"},"COP359": {"abstract": "When your applications include AI agents that reason, plan, and act autonomously, observability has to evolve too. Disconnected tools and siloed signals slow teams down right when speed matters most. In this chalk talk, we walk through real scenarios and trace an agent's chain of thought across services, correlating agent failures with infrastructure, and using natural-language investigation to cut resolution time. We diagram how service discovery, dependency mapping, evaluations, and IDE-native telemetry come together so you can ship agents with confidence.", "language": "en"},"COP360": {"abstract": "In this session, learn how to transform your finished application into a revenue-generating SaaS product. Learn about analyzing your cloud infrastructure, choose pricing models, and instrumenting code for usage metering. You'll see how to manage the complete billing lifecycle, from subscription management and invoicing to tax calculation and payment processing. Walk away with a clear path to accelerate your time-to-market and start charging customers.", "language": "en"},"COP361": {"abstract": "GPU and AI accelerators are the most expensive resources your teams run â€” and the hardest to observe when shared across teams. Most platform owners can't tell which workload is using which device, whether it's working or idle, or what a stalled run is costing per hour. When something degrades, teams find out after a crash or a surprise bill.Â This lightning talk explores how to spot what's sitting idle, pinpoint a failing device without sacrificing the healthy ones around it, and prioritize fixes by how much spend you can recover.", "language": "en"},"COP362": {"abstract": "Application issues can originate anywhere across the stack, from compute and container environments to networking, data, and AI services. In this session, see how AWS DevOps Agent investigates issues end to end across AWS, multicloud, and on-prem environments, analyzing telemetry and correlating signals across layers to pinpoint root causes and deliver targeted remediation. Learn how teams troubleshooting complex workloads can resolve issues faster and spend less time moving between tools and data sources.", "language": "en"},"COP363": {"abstract": "Production incidents typically involve multiple teams, but tooling and investigations are often siloed. In this chalk talk, explore how AWS DevOps Agent meets teams where incident response already happens. See how engineers can interact with the agent directly from tools like Slack, consolidating investigation activity, findings, and recommended actions alongside team communication. Bring your multi-team incident patterns and discuss approaches to faster, more connected incident response across AWS, multicloud, and on-prem environments.", "language": "en"},"COP363-R": {"abstract": "Production incidents typically involve multiple teams, but tooling and investigations are often siloed. In this chalk talk, explore how AWS DevOps Agent meets teams where incident response already happens. See how engineers can interact with the agent directly from tools like Slack, consolidating investigation activity, findings, and recommended actions alongside team communication. Bring your multi-team incident patterns and discuss approaches to faster, more connected incident response across AWS, multicloud, and on-prem environments.", "language": "en"},"COP364": {"abstract": "Periodic reviews can't keep pace with infrastructure that changes daily. In this hands-on workshop, deploy an AI-powered agent for continuous, goal-driven architecture reviews across a multi-account environment. Configure agent profiles, cross-account role chaining, and business goals that prioritize across Cost Optimization, Security, Resilience, and Performance pillars. See how the agent enriches Trusted Advisor, Compute Optimizer, and Resilience Hub signals with cross-pillar trade-off analysis. Run pre-deployment reviews against CloudFormation, CDK, and Terraform, then remediate through AI-generated SOPs. Wire recommendations into CI/CD via API. For architects, platform engineers, and operations leads who want always-on architectural governance in their delivery lifecycle.", "language": "en"},"COP364-R": {"abstract": "Periodic reviews can't keep pace with infrastructure that changes daily. In this hands-on workshop, stand up the AWS Well-Architected Agent for continuous, goal-driven reviews across a multi-account environment. Configure agent profiles, cross-account role chaining, and business goals that prioritize across Cost Optimization, Security, Resilience, and Performance pillars. See how the agent enriches Trusted Advisor, Compute Optimizer, and Resilience Hub signals with cross-pillar trade-off analysis. Run pre-deployment reviews against CloudFormation, CDK, and Terraform, then remediate through AI-generated SOPs. Wire recommendations into CI/CD via the Well-Architected API. For architects, platform engineers, and operations leads who want always-on architectural governance in their delivery lifecycle.", "language": "en"},"COP365": {"abstract": "Shared Amazon S3 buckets, Amazon EKS clusters, and network resources improve efficiency but can obscure which applications and business units drive spend. In this session, learn how to attribute shared costs based on actual usage. Follow a practical example using AWS Split Cost Allocation Data for S3 and EKS and Flexible Cost Allocation for networking. Then use AWS Cost Categories and Data Exports to combine each business unit’s share of storage, compute, and networking spend into a unified view. Walk away with a repeatable approach to showback and chargeback across your shared AWS environment.", "language": "en"},"COP366": {"abstract": "In this lightning talk, learn how to split any credit into precise amounts and transfer them to the accounts that need them. We walk through real-world workflows in the Console and API, show how split credits work seamlessly with sharing and pausing for full lifecycle control, and demonstrate how to replace monthly chargeback spreadsheets with a 5-minute workflow. Walk away with a playbook for giving every team a predictable credit budget as your organization scales.", "language": "en"},"COP367": {"abstract": "In this session, learn how to continuously assess and validate the operational resilience of your end-to-end business services using AWS Resilience Hub. See how GenAI agents automatically discover and map your application dependencies to give you a holistic picture of your resilience posture. Get actionable recommendations to close gaps, generate regulatory compliance artifacts to meet your compliance needs, and put it all to the test with end-to-end resilience testing to prove it.", "language": "en"},"COP368": {"abstract": "You moved to AWS Graviton for better price-performance, but is your disaster recovery keeping pace? A recovery that lands on the wrong architecture, or brings tiers up out of order, turns a routine failover into an outage. In this chalk talk, whiteboard with disaster recovery experts how AWS Elastic Disaster Recovery (DRS) now protects Graviton-based (arm64) Linux servers and recovers them onto Graviton instances, keeping the architecture intact end to end with nothing extra to configure. Then design a recovery plan that brings your application back tier by tier, in the right order, with wait times and critical-server gates. Bring your toughest arm64 and recovery-order questions, and leave with a DR design you can drill on Monday.", "language": "en"},"COP368-R": {"abstract": "You moved to AWS Graviton for better price-performance, but is your disaster recovery keeping pace? A recovery that lands on the wrong architecture, or brings tiers up out of order, turns a routine failover into an outage. In this chalk talk, whiteboard with disaster recovery experts how AWS Elastic Disaster Recovery (DRS) now protects Graviton-based (arm64) Linux servers and recovers them onto Graviton instances, keeping the architecture intact end to end with nothing extra to configure. Then design a recovery plan that brings your application back tier by tier, in the right order, with wait times and critical-server gates. Bring your toughest arm64 and recovery-order questions, and leave with a DR design you can drill on Monday.", "language": "en"},"COP401-R": {"abstract": "Multi-agent systems fail in ways your dashboards cannot show: one agent hands off bad context, another retries, and the API still returns 200. In this live coding session, start with a multi-agent app on LangGraph, Strands, and CrewAI, and instrument it with OpenTelemetry and OpenInference. Trace it from the first prototype run, evaluate agents on demand with LLM-as-judge evaluators, A/B test prompt and model variants before promoting to production, pull production traces into a versioned dataset, reproduce the failure locally, and ship the fix. All from your IDE, without switching tools.", "language": "en"},"COP401-R1": {"abstract": "Multi-agent systems fail in ways your dashboards cannot show: one agent hands off bad context, another retries, and the API still returns 200. In this live coding session, start with a multi-agent app on LangGraph, Strands, and CrewAI, and instrument it with OpenTelemetry and OpenInference. Trace it from the first prototype run, evaluate agents on demand with LLM-as-judge evaluators, A/B test prompt and model variants before promoting to production, pull production traces into a versioned dataset, reproduce the failure locally, and ship the fix. All from your IDE, without switching tools.", "language": "en"},"COP402-R": {"abstract": "Operational complexity doesn't scale linearly but your approach to managing it can. In this chalk talk, we'll use AWS DevOps Agent to explore three protocols shaping how operations teams work at scale: MCP (connecting to operational data and actions), ACP (delegating tasks to purpose-built agents), and A2A (coordinating across autonomous agents). We'll discuss how protocol choice affects decision-making, when to extend capabilities vs. delegate, and how to design architectures that grow with your operational footprint. Leave with a clear mental model for when to reach for each protocol and how they fit together.", "language": "en"},"COP402-R1": {"abstract": "Operational complexity doesn't scale linearly but your approach to managing it can. In this chalk talk, we'll use AWS DevOps Agent to explore three protocols shaping how operations teams work at scale: MCP (connecting to operational data and actions), ACP (delegating tasks to purpose-built agents), and A2A (coordinating across autonomous agents). We'll discuss how protocol choice affects decision-making, when to extend capabilities vs. delegate, and how to design architectures that grow with your operational footprint. Leave with a clear mental model for when to reach for each protocol and how they fit together.", "language": "en"},"COP403-R": {"abstract": "As AI workloads scale, engineers face complex trade-offs between cost, latency, and response quality. This code talk explores advanced optimisation techniques for production AI applications on Amazon Bedrock: prompt engineering, model selection, caching, and context window management. Through live coding, attendees examine the reasoning behind each design decision, observe cost impact via AWS Billing and Cost Management, and learn to instrument apps to detect performance regressions. Understanding the tokenomics of your AI stack is essential to operating efficiently at scale.", "language": "en"},"COP403-R1": {"abstract": "As AI workloads scale, engineers face complex trade-offs between cost, latency, and response quality. This code talk explores advanced optimisation techniques for production AI applications on Amazon Bedrock: prompt engineering, model selection, caching, and context window management. Through live coding, attendees examine the reasoning behind each design decision, observe cost impact via AWS Billing and Cost Management, and learn to instrument apps to detect performance regressions. Understanding the tokenomics of your AI stack is essential to operating efficiently at scale.", "language": "en"},"COP404": {"abstract": "Your AI agents need production-grade orchestration, but should you own the loop or let AWS handle it? We build one on-call responder three ways: an Amazon Bedrock AgentCore harness for a managed loop with built-in memory and tool routing, AgentCore Runtime for full control, and AWS DevOps Agent as a batteries-included DevOps harness. Then we build the shape most teams land in: your own orchestrator, DevOps Agent composed in headless over remote MCP and A2A. Bring your challenges and leave with patterns for building composable, robust pipelines that automate complex DevOps workflows end-to-end.", "language": "en"},"COP405-R": {"abstract": "LLMs hallucinate. Code doesn't. When your AI agent investigates a production incident, some answers demand computation, not just reasoning. In this code talk, we crack open the sandbox in AWS DevOps Agent: an ephemeral, investigation-scoped Linux environment where the agent writes and runs code inside a Lambda MicroVM with read-only AWS access and zero lateral blast radius. We'll discuss how networking allowlists, pre-installed packages, and executable skills give you deterministic, auditable results for log parsing, metric correlation, and multi-source analysis. Bring your problems and we'll whiteboard the isolation boundaries live.", "language": "en"},"COP405-R1": {"abstract": "LLMs hallucinate. Code doesn't. When your AI agent investigates a production incident, some answers demand computation, not just reasoning. In this code talk, we crack open the sandbox in AWS DevOps Agent: an ephemeral, investigation-scoped Linux environment where the agent writes and runs code inside a Lambda MicroVM with read-only AWS access and zero lateral blast radius. We'll discuss how networking allowlists, pre-installed packages, and executable skills give you deterministic, auditable results for log parsing, metric correlation, and multi-source analysis. Bring your problems and we'll whiteboard the isolation boundaries live.", "language": "en"},"COP406-R": {"abstract": "GitOps was designed for human-speed change. Agentic coding tools now generate pull requests faster than any team can review and safely release. Your release process is the new bottleneck. In this code talk, we'll live-code a GitOps release workflow where AWS DevOps Agent acts as an intelligent release manager, validating the results through a release pipeline at every promotion gate. Instead of manual approvals, DevOps Agent uses production intelligence (runtime dependencies, service health, deployment risk) to make real-time go/no-go decisions. Learn how to wire DevOps Agent into your GitOps reconciliation loop so releases match the velocity of agentic code generation without sacrificing safety.", "language": "en"},"COP406-R1": {"abstract": "GitOps was designed for human-speed change. Agentic coding tools now generate pull requests faster than any team can review and safely release. Your release process is the new bottleneck. In this code talk, we'll live-code a GitOps release workflow where AWS DevOps Agent acts as an intelligent release manager, validating the results through a release pipeline at every promotion gate. Instead of manual approvals, DevOps Agent uses production intelligence (runtime dependencies, service health, deployment risk) to make real-time go/no-go decisions. Learn how to wire DevOps Agent into your GitOps reconciliation loop so releases match the velocity of agentic code generation without sacrificing safety.", "language": "en"},"COP407": {"abstract": "AI agents can fix production issues, but only with the right context. In this talk, an AI agent builds a feature and, in the same pull request, creates the context it needs on call: instrumentation, alarms, dashboards, and skills, all as code. Then you break the live app. Watch an agent use those skills with Amazon CloudWatch Omni and AWS DevOps Agent to triage, find the root cause, and ship the fix. Leave with patterns that give agents the context to operate what they build.", "language": "en"},"COP408": {"abstract": "Diagnosing performance degradation across distributed applications requires more than isolated database or application metrics. It demands correlated, end-to-end telemetry. This code talk demonstrates a scenario that unifies database performance signals with application-layer telemetry using OpenTelemetry and Amazon CloudWatch. Learn how to implement trace-to-query correlation, design log aggregation patterns for accelerated root cause analysis, and build metric relationships that surface bottlenecks across the full stack. You'll be able to connect a slow database query to its downstream user impact.", "language": "en"},"COP408-R": {"abstract": "Diagnosing performance degradation across distributed applications requires more than isolated database or application metrics. It demands correlated, end-to-end telemetry. This code talk demonstrates a scenario that unifies database performance signals with application-layer telemetry using OpenTelemetry and Amazon CloudWatch. Learn how to implement trace-to-query correlation, design log aggregation patterns for accelerated root cause analysis, and build metric relationships that surface bottlenecks across the full stack. You'll be able to connect a slow database query to its downstream user impact.", "language": "en"},"COP409": {"abstract": "Diagnosing latency across a high-scale Amazon EKS environment is complex when pods scale dynamically and trace context fails to propagate across service boundaries. In this code talk, we instrument containerized microservices with OpenTelemetry, propagate context across service hops, and correlate spans, metrics, and logs in Amazon CloudWatch. Live coding shows how a single slow request reveals the exact container and code path responsible for degradation, using targeted span attributes and exemplars to make Kubernetes-scale traces navigable. You'll also see the trade-offs behind sampling strategies and collector deployment topologies that affect overhead, fidelity, and cost at production scale.", "language": "en"},"COP410-R": {"abstract": "You want open standards without the operational burden of self-managing backends. In this code talk, we live-code a complete open source observability architecture: instrument a service with OpenTelemetry (auto and manual), configure the OTel Collector pipeline, and route metrics to Amazon Managed Service for Prometheus, logs and traces to Amazon OpenSearch Service. Walk through each integration decision from SDK selection to collector topology, and leave with a working, production-ready stack built entirely on open source standards with zero infrastructure to manage.", "language": "en"},"COP410-R1": {"abstract": "You want open standards without the operational burden of self-managing backends. In this code talk, we live-code a complete open source observability architecture: instrument a service with OpenTelemetry (auto and manual), configure the OTel Collector pipeline, and route metrics to Amazon Managed Service for Prometheus, logs and traces to Amazon OpenSearch Service. Walk through each integration decision from SDK selection to collector topology, and leave with a working, production-ready stack built entirely on open source standards with zero infrastructure to manage.", "language": "en"},"COP411": {"abstract": "Why is it so hard to connect a production alert to the code change that caused it? Metrics and traces reveal something is wrong but stop short of the function responsible. Developers guess which deployment introduced the regression, manually correlating dashboards with recent commits. Meanwhile, AI coding agents that could help write fixes are blind to runtime behavior. In this code talk, we'll explore how to close the gap between observability signals and the code your team owns, what new signals make that connection possible, how developers and AI agents can consume them, and what changes when observability reaches the code level.", "language": "en"},"DAT101-S": {"abstract": "Oracle AI Database@AWS gives organizations a new way to bring mission-critical Oracle data closer to their applications, analytics, and AI services in AWS. This session shares a clear overview of the multicloud value proposition, including application proximity, operational simplicity, enterprise performance, security, and access to AWS services. Three Oracle industry leaders will explore what that value looks like in practice. Hear how financial institutions can strengthen fraud detection, risk management, and customer experiences; how healthcare organizations can generate trusted clinical and operational insights; and how manufacturers can improve forecasting, supply chain decisions, asset performance, and operational efficiency. Leave with a practical understanding of Oracle AI Database@AWS and concrete examples of how multicloud can support industry-specific AI and business outcomes. This presentation is brought to you by Oracle, an AWS Partner.", "language": "en"},"DAT201-S": {"abstract": "Seventy-four percent of industrial IoT projects stall somewhere between pilot and production. The hard part is that the pilot worked. That is exactly what makes the failure so difficult to diagnose. Pilots succeed because a few hundred sensors over a few weeks fits comfortably in almost any database. Production does not. Storage costs compound faster than the budget that approved them, ingest hits a cliff with no warning, and the real-time dashboard that sold the project turns into a loading screen. See where industrial systems and typical AWS pipelines reach their limits and how to scale beyond them. We’ll explore a proven architecture using AWS IoT Core, Amazon Kinesis, AWS Lambda, and a single Postgres database to support more than one million connected devices reporting every second. This presentation is brought to you by Tiger Data, an AWS Partner.", "language": "en"},"DAT202-S": {"abstract": "How do you keep an agent's understanding of the world fresh enough for it to act on? Interactive agents need current context about the customers, orders, inventory, accounts, and other entities they reason about. But assembling that context from constantly changing operational systems is complex, forcing teams to choose between stale data, expensive recomputation, or complex pipelines. This talk will show how to build continuously updated context in SQL that is trustworthy enough for agents to rely upon. You'll learn how to transform operational data into agent-ready representations, keep attributes and relationships up to date as the underlying data changes, and propagate those changes to search indexes and embeddings when needed. Attend if you're deploying AI agents to production and want to give them fresher, more complete context and tighten their read-act-react loop. This presentation is brought to you by Materialize, an AWS Partner.", "language": "en"},"DAT203-S": {"abstract": "An agent needs a Postgres database for perhaps twenty minutes. A payments platform needs one that never goes down across three regions. Most teams cover that range with different products, several vendors, and scores of on-call operators. Yugabyte delivers it as a single stack on AWS. YugabyteDB is distributed PostgreSQL built for global scale and resilience that also scales down to fractional instances. YugabyteDB AMP puts agents in charge of the fleet, handling provisioning, migration, and on-demand tuning. Meko gives agent teams the shared context they run on. See what it takes to run every Postgres workload on one foundation. This presentation is brought to you by YugabyteDB, an AWS Partner.", "language": "en"},"DAT301-R": {"abstract": "Maintaining performance for Amazon Aurora and Amazon RDS often requires manual effort, such as tuning queries, managing indexes, and handling alerts. In this builders' session, learn how to leverage agentic AI solutions implementing LLM-powered autonomous agents to monitor, diagnose, and optimize relational databases in real time. We will demonstrate how AI agents can analyze slow query logs, recommend or apply tuning actions, and trigger intelligent alerts using Amazon Bedrock, Amazon Cloudwatch, AWS Lambda, and Amazon Systems Manager. Bring your laptop to participate.", "language": "en"},"DAT301-R1": {"abstract": "Maintaining performance for Amazon Aurora and Amazon RDS often requires manual effort, such as tuning queries, managing indexes, and handling alerts. In this builders' session, learn how to leverage agentic AI solutions implementing LLM-powered autonomous agents to monitor, diagnose, and optimize relational databases in real time. We will demonstrate how AI agents can analyze slow query logs, recommend or apply tuning actions, and trigger intelligent alerts using Amazon Bedrock, Amazon Cloudwatch, AWS Lambda, and Amazon Systems Manager. Bring your laptop to participate.", "language": "en"},"DAT302-R": {"abstract": "Amazon Aurora is a cloud-native managed relational database that lets you create, manage, and scale your database resources with ease. In this session, dive deep into Aurora cost components and see how you can use cost-focused features and tooling to optimize costs for your workload without sacrificing performance or scale. Learn how the Aurora I/O-Optimized configuration can help you achieve cost savings for I/O-intensive workloads, and discover how Database Savings Plans can provide additional cost reductions through flexible commitment-based pricing.", "language": "en"},"DAT302-R1": {"abstract": "Amazon Aurora is a cloud-native managed relational database that lets you create, manage, and scale your database resources with ease. In this session, dive deep into Aurora cost components and see how you can use cost-focused features and tooling to optimize costs for your workload without sacrificing performance or scale. Learn how the Aurora I/O-Optimized configuration can help you achieve cost savings for I/O-intensive workloads, and discover how Database Savings Plans can provide additional cost reductions through flexible commitment-based pricing.", "language": "en"},"DAT303": {"abstract": "Explore high availability (HA) and disaster recovery (DR) design patterns for SQL Server and Oracle databases on Amazon RDS. In this session, learn about the features offered by Amazon RDS for business continuity, including Multi-AZ deployments, read replicas, and cross-region replication. Discover the customizations that Amazon RDS enables for HA and DR while also allowing you to bring your own license (BYOL) for SQL Server. Also learn how globally resilient solutions architected with Amazon RDS minimize downtime and meet stringent business continuity requirements for mission-critical workloads.", "language": "en"},"DAT304-R": {"abstract": "Blue/green deployments for Amazon Aurora and Amazon RDS simplify the process of upgrading and performing maintenance on your databases. In this chalk talk, you will architect a blue/green database upgrade solution to support major or minor engine version upgrades and perform schema changes with minimal and predictable downtime. Active participation is encouraged as you architect a solution to meet your requirements. In open discussion, learn the trade-offs involved in database management when using blue/green deployments and how to design the most effective upgrade solution to meet your needs.", "language": "en"},"DAT304-R1": {"abstract": "Blue/green deployments for Amazon Aurora and Amazon RDS simplify the process of upgrading and performing maintenance on your databases. In this chalk talk, you will architect a blue/green database upgrade solution to support major or minor engine version upgrades and perform schema changes with minimal and predictable downtime. Active participation is encouraged as you architect a solution to meet your requirements. In open discussion, learn the trade-offs involved in database management when using blue/green deployments and how to design the most effective upgrade solution to meet your needs.", "language": "en"},"DAT306-R": {"abstract": "Developers love building on powerful, serverless Amazon DynamoDB, and as their production tables grow in size and traffic, they want to discover what mechanisms and optimizations can be applied to reduce costs. Cost optimization can be done both in the design phase and during operations. In this session, learn how to model and measure costs, explore Database Savings Plans to reduce spend on predictable workloads, and discover cost optimization tools that can help you along the way.", "language": "en"},"DAT306-R1": {"abstract": "Developers love building on powerful, serverless Amazon DynamoDB, and as their production tables grow in size and traffic, they want to discover what mechanisms and optimizations can be applied to reduce costs. Cost optimization can be done both in the design phase and during operations. In this session, learn how to model and measure costs, explore Database Savings Plans to reduce spend on predictable workloads, and discover cost optimization tools that can help you along the way.", "language": "en"},"DAT307-R": {"abstract": "How do you take an AI agent from a local prototype to a governed application that recovers from failure? In this session, follow a reference application through five phases: querying business data with SQL, connecting agents to Model Context Protocol (MCP) tools, adding hybrid retrieval, deploying to production, and enabling durable workflows. See how Aurora PostgreSQL unifies relational data, pgvector embeddings, full-text search, and workflow state. Explore Strands Agents on Bedrock AgentCore, verify identity and enforce row-level security for data access, and govern tool calls with AgentCore Policy. Code walkthroughs show recovery from saved steps, idempotency to prevent duplicate actions, and audit records that make outcomes traceable.", "language": "en"},"DAT307-R1": {"abstract": "How do you take an AI agent from a local prototype to a governed application that recovers from failure? In this session, follow a reference application through five phases: querying business data with SQL, connecting agents to Model Context Protocol (MCP) tools, adding hybrid retrieval, deploying to production, and enabling durable workflows. See how Aurora PostgreSQL unifies relational data, pgvector embeddings, full-text search, and workflow state. Explore Strands Agents on Bedrock AgentCore, verify identity and enforce row-level security for data access, and govern tool calls with AgentCore Policy. Code walkthroughs show recovery from saved steps, idempotency to prevent duplicate actions, and audit records that make outcomes traceable.", "language": "en"},"DAT307-R2": {"abstract": "How do you take an AI agent from a local prototype to a governed application that recovers from failure? In this session, follow a reference application through five phases: querying business data with SQL, connecting agents to Model Context Protocol (MCP) tools, adding hybrid retrieval, deploying to production, and enabling durable workflows. See how Aurora PostgreSQL unifies relational data, pgvector embeddings, full-text search, and workflow state. Explore Strands Agents on Bedrock AgentCore, verify identity and enforce row-level security for data access, and govern tool calls with AgentCore Policy. Code walkthroughs show recovery from saved steps, idempotency to prevent duplicate actions, and audit records that make outcomes traceable.", "language": "en"},"DAT311": {"abstract": "The emergence of digital assets and stablecoins requires bridging traditional message-based finance protocols such as SWIFT and ISO 20022 to programmable settlement rails while preserving institutional security, auditability, and governance. In this session, learn how to build a production-ready end-to-end hybrid settlement architecture on AWS that ingests financial messages, normalizes them into canonical settlement instructions, and executes tokenized asset transfers on-chain. Explore hardware-backed signing with AWS KMS, on-chain signer governance, and three settlement patterns: issuance, redemption, and transfer, with full audit trails, idempotent transaction handling, and EIP-712 typed signing. Bring your laptop to participate.", "language": "en"},"DAT312": {"abstract": "Cost and performance are top of mind for customers, and these topics go hand in hand. In this chalk talk, learn how to deploy a performant and cost-effective Amazon RDS for SQL Server solution that fits your needs. Explore RDS monitoring tools and native SQL Server features that can be leveraged to pinpoint query inefficiencies, optimize workloads, and right-size your database instances for both cost and peak performance.", "language": "en"},"DAT313": {"abstract": "Dedicated Exadata infrastructure inside AWS data centers gives Oracle workloads full feature compatibility alongside cloud native flexibility, but architecting for resiliency at scale demands deliberate design choices. In this session, explore architecture patterns for primary and disaster recovery deployments on Oracle Database@AWS, including strategies for multi-terabyte migration and managing petabyte-scale Oracle estates. Join a live whiteboarding discussion where AWS experts cover ODB@AWS deployment options, DR configurations, and operational design choices. Architect with validated best practices drawn from real customer deployments.", "language": "en"},"DAT314": {"abstract": "Centralized exchanges, decentralized exchanges, and prediction markets share a critical challenge: managing the tension between resiliency and latency. AWS customers have solved this at scale on low-latency platforms trading digital assets 24/7. In this session, AWS specialists dive deep into architecture patterns and real-world examples addressing each challenge. Learn best practices for designing resilient, low-latency trading infrastructure using the latest AWS capabilities built for these markets.", "language": "en"},"DAT315": {"abstract": "Managing ride-hailing demand across 1,100+ cities and 8+ million daily transactions in real time requires scalable, resilient, sub-millisecond in-memory data operations. In this session, learn how inDrive evolved from a monolithic on-premises Redis OSS cluster to over 400 distributed Amazon ElastiCache clusters spanning 8 AWS Regions, executing 1.3 trillion operations daily. Discover how inDrive eliminated bottlenecks in single-CPU utilization, network saturation, and hotspot shards, and how a zero-downtime migration to the Valkey engine on ElastiCache improved performance and reduced costs. Learn a production-tested blueprint for scaling data-intensive systems across multiple AWS Regions.", "language": "en"},"DAT316": {"abstract": "Expedia Group manages thousands of database instances across hundreds of AWS accounts. When incidents strike at this scale, every second counts. In this session, learn how a customer-driven vision for agentic AI evolved into a joint design partnership for autonomous database operations on Amazon Aurora. Discover how agents diagnose incidents across fleet-scale telemetry and deliver actionable recommendations to engineers. This joint initiative demonstrates how AI agents reduce incident response time and serves as a blueprint for teams seeking to automate database operations at scale. Learn how AWS is building the underlying capabilities to make autonomous operations real.", "language": "en"},"DAT317": {"abstract": "In this session, gain the skills needed to deploy end-to-end agentic AI applications using your most valuable data. This session focuses on data management using processes like Model Context Protocol (MCP) and Retrieval Augmented Generation (RAG), and provides concepts that apply to other methods of customizing agentic AI applications. Discover best practice architectures using AWS database services like Amazon Aurora, DynamoDB, and Neptune, along with analytical, data processing and streaming experiences found in SageMaker. Learn data lake, governance, and data quality concepts and how Amazon Bedrock AgentCore and Bedrock Knowledge Bases, and other features tie solution components together.", "language": "en"},"DAT318-S": {"abstract": "At billion-vector scale, vector index construction can become a performance and cost bottleneck for retrieval, RAG, and AI workloads. Amazon OpenSearch Service Vector Acceleration uses NVIDIA cuVS to accelerate index construction, delivering up to 10x faster builds at a quarter of the indexing cost while preserving the OpenSearch experience. This 300-level session goes under the hood of the architecture: how eligible builds are offloaded to managed GPU workers, how cuVS and CAGRA accelerate graph construction through the Faiss backend, and how the graph is converted into an HNSW index for CPU-based search. We will examine how segment size, quantization, and ingestion patterns affect GPU utilization, build speed, and efficiency. Attendees will leave with guidance for identifying good-fit workloads, optimizing ingestion, and modeling performance and cost benefits for their own deployments. This presentation is brought to you by NVIDIA, an AWS Partner.", "language": "en"},"DAT319-S": {"abstract": "Human queries are bounded, repeatable, and predictable, so techniques like caching, sampling, and precomputation keep them fast and affordable. AI agents are none of those. One prompt becomes dozens of novel, complex queries at machine speed, so caching an agent's curiosity is nearly impossible. At a leading automotive R&D group, 1,400 engineers and their agents query 200 petabytes of vehicle telemetry, with 600 terabytes ingested daily, to engineer higher-quality, more reliable vehicles and reach production faster. This session shows the AWS architecture behind it and how it delivers real-time analytics with full retention at the scale agents have made standard. This presentation is brought to you by Edelbyte, an AWS Partner.", "language": "en"},"DAT321": {"abstract": "What does it take to migrate the databases behind 5 million small businesses without anyone noticing? Xero, the global cloud accounting platform, moved 900 SQL Server databases to Amazon RDS for SQL Server with near-zero downtime. In this session, Xero shares how the team orchestrated cutovers, approached schema migration, and used managed patching, automated backups, and capacity planning in Amazon RDS to return engineering time to product development. The session covers the migration planning and decision points most relevant to engineering teams running large SQL Server fleets on aging self-managed infrastructure.", "language": "en"},"DAT401": {"abstract": "Amazon Aurora is a serverless relational database with unparalleled high performance and availability at global scale for PostgreSQL, MySQL, and DSQL. Aurora provides managed high availability (HA) and disaster recovery (DR) capabilities in and across AWS Regions. In this session, explore the Aurora HA and DR capabilities and discover design patterns that enable the development of resilient applications. Learn how to establish in-Region and cross-Region HA and DR using Aurora features including Multi-AZ deployments and Aurora Global Database, and how Aurora DSQL multi-Region clusters provides the highest level of availability and application resilience.", "language": "en"},"DAT402": {"abstract": "Migrating from Oracle to Amazon Aurora PostgreSQL-Compatible Edition can be a transformative journey, offering significant cost savings and performance benefits. However, this transition requires careful planning and execution. In this session, discover the essential things you need to know to ensure a smooth and successful migration from Oracle to Aurora PostgreSQL and the optimal architectures to enable such a migration. Learn best practices and pitfalls to avoid from seasoned experts who have helped many customers walk this path.", "language": "en"},"DAT403": {"abstract": "In this live coding session, we'll show you how to work with Amazon Aurora DSQL from a developer's perspective. We'll develop a sample application to highlight some of the ways developing for Aurora DSQL is different than PostgreSQL. We'll cover authentication and connection management, optimistic concurrency transaction patterns, primary key selection, analyzing query performance, and best practices.", "language": "en"},"DAT404-R": {"abstract": "Recent PostgreSQL releases introduced transformative capabilities for logical replication and partitioning, including filtering, parallel apply, sequence replication, and improved planning for partition-heavy workloads. These features are powerful, but tuning them for a specific environment remains complex. In this session, learn to build agents for these core PostgreSQL concepts on Amazon Aurora PostgreSQL: one that analyzes workloads to recommend optimal logical replication configuration, and a partitioning agent that evaluates query patterns and table bloat to guide table partitioning strategy.", "language": "en"},"DAT404-R1": {"abstract": "Recent PostgreSQL releases introduced transformative capabilities for logical replication and partitioning, including filtering, parallel apply, sequence replication, and improved planning for partition-heavy workloads. These features are powerful, but tuning them for a specific environment remains complex. In this session, learn to build agents for these core PostgreSQL concepts on Amazon Aurora PostgreSQL: one that analyzes workloads to recommend optimal logical replication configuration, and a partitioning agent that evaluates query patterns and table bloat to guide table partitioning strategy.", "language": "en"},"DAT404-R2": {"abstract": "Recent PostgreSQL releases introduced transformative capabilities for logical replication and partitioning, including filtering, parallel apply, sequence replication, and improved planning for partition-heavy workloads. These features are powerful, but tuning them for a specific environment remains complex. In this session, learn to build agents for these core PostgreSQL concepts on Amazon Aurora PostgreSQL: one that analyzes workloads to recommend optimal logical replication configuration, and a partitioning agent that evaluates query patterns and table bloat to guide table partitioning strategy.", "language": "en"},"DAT405": {"abstract": "Amazon Aurora DSQL is a serverless, distributed SQL database that uses decades of Amazon innovation and operational excellence. In this session, dive into the design and key innovative technologies that make Aurora DSQL the ideal choice for new applications and applications that require the highest level of resilience. Learn how active-active architecture in Aurora DSQL delivers single- and multi-Region resiliency and virtually unlimited scale", "language": "en"},"DAT406-R": {"abstract": "GraphRAG combines knowledge graphs with RAG to produce explainable responses grounded in semantic relationships between concepts, entities, and underlying content. Agentic GraphRAG takes this further, allowing agents to autonomously decide which GraphRAG tools to use to achieve information goals. In this session, build an agentic GraphRAG application using the open source AWS GraphRAG Toolkit. You will transform unstructured and semi-structured data into a catalog of domain-specific GraphRAG tools to enable agents to answer multi-faceted questions that require context from multiple distinct knowledge sources to provide a contextually complete answer. Bring your laptop to participate.", "language": "en"},"DAT406-R1": {"abstract": "GraphRAG combines knowledge graphs with RAG to produce explainable responses grounded in semantic relationships between concepts, entities, and underlying content. Agentic GraphRAG takes this further, allowing agents to autonomously decide which GraphRAG tools to use to achieve information goals. In this session, build an agentic GraphRAG application using the open source AWS GraphRAG Toolkit. You will transform unstructured and semi-structured data into a catalog of domain-specific GraphRAG tools to enable agents to answer multi-faceted questions that require context from multiple distinct knowledge sources to provide a contextually complete answer. Bring your laptop to participate.", "language": "en"},"DAT407": {"abstract": "Amazon DynamoDB supports native vector search, enabling semantic queries, agentic recommendations, and image-based matching without additional infrastructure. In this session, explore how to design a single-table data model for a recipe database, bulk-load thousands of items with embeddings, and build three vector-powered features: semantic search, a smart recommendation agent, and image-based meal matching. Learn how to configure vector indexes, composite keys, and global secondary indexes on a fully serverless stack, and leave with reusable patterns to add vector search to your own DynamoDB workloads. Bring your laptop to participate.", "language": "en"}};
  window.APP_DATA.sessions.forEach(function (s) {
    var x = m[s.session_id];
    if (x) for (var k in x) if (x[k]) s[k] = x[k];
  });
})();
